{-# LANGUAGE MultiWayIf #-}

-- | Replays @differential/hands_corpus.json@ (generated by
-- @differential/hands_corpus.py@ from the reference) against the Haskell
-- Hands contract, grants and gateway.
module Petrus.Agenticus.Hands.DifferentialSpec (spec) where

import Control.Exception (throwIO, try)
import Control.Monad (forM, unless, when)
import Data.IORef
import Data.Map.Strict qualified as Map
import Data.Maybe (catMaybes, fromMaybe)
import Data.Set qualified as Set
import Data.Text (Text)
import Data.Text qualified as T
import Data.Text.Encoding qualified as TE
import Petrus.Agenticus.Error
import Petrus.Agenticus.Hands.Contract
import Petrus.Agenticus.Hands.Gateway
import Petrus.Agenticus.Hands.Gateway qualified as G
import Petrus.Agenticus.Hands.Grants
import Petrus.Agenticus.Internal.Validate (sha256Hex)
import Petrus.Agenticus.Support (loadJson)
import Petrus.Json (Json (..))
import Petrus.Json qualified as J
import Test.Hspec

corpusFile :: FilePath
corpusFile = "differential/hands_corpus.json"

at :: Text -> Json -> Json
at key j = fromMaybe Null (J.lookupMember key j)

items :: Json -> [Json]
items = \case
  Array xs -> xs
  _ -> []

text :: Json -> Text
text = \case
  String t -> t
  other -> error ("expected a string, got " <> show other)

int :: Json -> Integer
int = \case
  Int i -> i
  other -> error ("expected an integer, got " <> show other)

double :: Json -> Double
double = \case
  Int i -> fromInteger i
  Float d -> d
  String "inf" -> 1 / 0
  String "-inf" -> -1 / 0
  String "nan" -> 0 / 0
  other -> error ("expected a number, got " <> show other)

bool :: Json -> Bool
bool = \case
  Bool b -> b
  other -> error ("expected a boolean, got " <> show other)

texts :: Json -> [Text]
texts = map text . items

method :: Json -> ToolMethod
method j = fromMaybe (error "unknown method") (parseToolMethod (text j))

refusal :: AgenticusError -> Json
refusal e = Object [("class", String (errorClassName e.errorClass)), ("message", String e.errorMessage)]

dumpsText :: Json -> Text
dumpsText = either (error . show) TE.decodeUtf8 . J.dumps J.defaultDumps

-- | Every mismatch as a labelled message; the example fails on the first few.
expectNone :: [String] -> Expectation
expectNone mismatches =
  unless (null mismatches) $
    expectationFailure (show (length mismatches) <> " mismatches:\n" <> unlines (take 5 mismatches))

mismatch :: String -> Json -> Json -> Maybe String
mismatch label expected got
  | J.exactEq expected got = Nothing
  | otherwise = Just (label <> "\n  expected " <> show expected <> "\n  got      " <> show got)

requestOutcome :: Json -> Json
requestOutcome input = case parseToolRequest input of
  Right r -> Object [("request", toolRequestToData r)]
  Left r ->
    Object
      [ ( "rejected"
        , Object
            [ ("category", String (rejectionCategoryText r.category))
            , ("detail", String r.detail)
            , ("message", String (rejectedMessage r))
            ]
        )
      ]

resultOutcome :: Json -> Json
resultOutcome input =
  case build of
    Left e -> Object [("error", refusal e)]
    Right r -> Object [("to_data", String (dumpsText (toolResultToData r))), ("model", String (dumpsText (toolResultToModelData r)))]
  where
    build = do
      failure <- case items (at "error" input) of
        [c, d] -> Just <$> mkToolError (fromMaybe (error "category") (parseRejectionCategory (text c))) (text d)
        _ -> Right Nothing
      let data' = case at "data" input of
            Object members -> Just members
            _ -> Nothing
      mkToolResult (text (at "call_id" input)) (text (at "attachment_id" input)) (int (at "epoch" input)) (bool (at "ok" input)) data' failure

grantOutcome :: [Text] -> Json -> Json
grantOutcome probes input = case grant of
  Left e -> Object [("error", refusal e)]
  Right g ->
    Object
      [ ("permits", Array [Bool (permits g m) | m <- allToolMethods])
      , ("permits_write_path", Array [Bool (permitsWritePath g p) | p <- probes])
      , ("deadline", Float g.deadline)
      ]
  where
    grant =
      mkCapabilityGrant
        (text (at "attachment_id" input))
        (int (at "attachment_epoch" input))
        (int (at "grant_epoch" input))
        (map method (items (at "capabilities" input)))
        (texts (at "writable_paths" input))
        (map texts (items (at "allowed_argv" input)))
        (double (at "deadline" input))
        (int (at "max_calls" input))
        (texts (at "writable_roots" input))
        (texts (at "denied_writable_roots" input))

-- | The corpus's deterministic @SessionAdapter@ (over the session's
-- stages, fence, clock and ledger).
sessionAdapter :: IORef (Map.Map Text Text) -> IORef CallFence -> IORef Double -> GrantLedger -> HandsAdapter
sessionAdapter stages fence now ledger =
  HandsAdapter
    { read = \path -> if
        | "boom" `T.isPrefixOf` path -> secret
        | "big" `T.isPrefixOf` path -> pure (T.replicate 5000 "x")
        | otherwise -> do
            when ("late" `T.isPrefixOf` path) $ writeIORef now 500
            when ("closing" `T.isPrefixOf` path) $ modifyIORef' fence (\f -> callFence False f.aborted f.deadline)
            pure ("content:" <> path)
    , search = \query path -> if
        | query == "many" -> pure ["m" <> T.pack (show i) | i <- [0 .. 64 :: Int]]
        | "boom" `T.isPrefixOf` path -> secret
        | otherwise -> pure [query <> "@" <> path]
    , shell = \argv cwd -> case argv of
        "fail" : _ -> secret
        _ -> either throwIO pure (mkShellOutcome (fromIntegral (length argv)) (T.unwords argv) cwd False)
    , stageWrite = \call path content ->
        if "boom" `T.isPrefixOf` path
          then secret
          else do
            modifyIORef' stages (Map.insert call content)
            when ("abort" `T.isPrefixOf` path) $ modifyIORef' fence (\f -> callFence f.open True f.deadline)
            when ("regrant" `T.isPrefixOf` path) $
              currentGrant ledger >>= mapM_ (openGrant ledger . sameSpec)
            let path' = if "skew" `T.isPrefixOf` path then path <> "x" else path
            either throwIO pure (mkStagedWrite call path' (sha256Hex (TE.encodeUtf8 content)))
    , commitWrite = \staged ->
        if "crash" `T.isPrefixOf` staged.path || "nodiscard" `T.isPrefixOf` staged.path
          then secret
          else do
            modifyIORef' stages (Map.delete staged.callId)
            pure (if "bad" `T.isPrefixOf` staged.path then T.replicate 64 "0" else staged.digest)
    , discardWrite = \staged ->
        if "nodiscard" `T.isPrefixOf` staged.path then secret else modifyIORef' stages (Map.delete staged.callId)
    , runTest = do
        outstanding <- readIORef stages
        either throwIO pure (mkTestOutcome (Map.null outstanding) (T.replicate 64 "e"))
    , discardAllStages = do
        outstanding <- readIORef stages
        writeIORef stages Map.empty
        pure (Map.size outstanding)
    }
  where
    secret :: IO a
    secret = throwIO (userError "SECRET")
    sameSpec g =
      (grantSpec (Set.toList g.capabilities) g.deadline g.maxCalls)
        { specWritablePaths = Set.toList g.writablePaths
        , specWritableRoots = Set.toList g.writableRoots
        , specDeniedWritableRoots = Set.toList g.deniedWritableRoots
        , specAllowedArgv = Set.toList g.allowedArgv
        }

countersData :: GatewayCounters -> Json
countersData c =
  Object
    [ ("requests", n c.requests)
    , ("rejections", Object [(rejectionCategoryText k, n v) | (k, v) <- Map.toList c.rejections])
    , ("adapter_entries", n c.adapterEntries)
    , ("stages", n c.stages)
    , ("commits", n c.commits)
    , ("stage_discards", n c.stageDiscards)
    , ("stage_discard_failures", n c.stageDiscardFailures)
    , ("target_mutations", n c.targetMutations)
    , ("results_admitted", n c.resultsAdmitted)
    ]
  where
    n = Int . fromIntegral

evidenceData :: [CallEvidence] -> Json
evidenceData es =
  Array
    [ Object
        [ ("sequence", Int (fromIntegral e.sequence))
        , ("call_id", String e.callId)
        , ("episode_id", String e.episodeId)
        , ("method", maybe Null (String . toolMethodText) e.method)
        , ("ok", Bool e.ok)
        , ("category", maybe Null (String . rejectionCategoryText) e.category)
        , ("epoch", Int e.epoch)
        ]
    | e <- es
    ]

-- | Replay one session, returning every mismatch.
replaySession :: Json -> IO [String]
replaySession session = do
  let label = T.unpack (text (at "label" session))
      config = at "config" session
  fence <- newIORef (callFence True False 100)
  now <- newIORef (1 :: Double)
  current <- newIORef True
  stages <- newIORef Map.empty
  ledger <- newGrantLedger "attachment-1" 3
  barrier' <- newBarrier
  gw <-
    newHandsGateway
      (gatewayConfig "episode-1" (sessionAdapter stages fence now ledger) ledger (CallFenceSource (readIORef fence)) barrier')
        { G.clock = readIORef now
        , maxGatewayCalls = fromIntegral (int (at "max_calls" config))
        , G.maxEvidence = fromIntegral (int (at "max_evidence" config))
        , G.admission = if bool (at "admission" config) then Just (ResultAdmission (pure . not . T.isInfixOf "deny")) else Nothing
        , G.target = if bool (at "target" config) then Just (TargetCurrency (readIORef current)) else Nothing
        }
  stepMismatches <- forM (zip [0 :: Int ..] (items (at "steps" session))) $ \(index, step) -> do
    let op = at "step" step
        expected = at "outcome" step
        here = label <> " step " <> show index <> " " <> show op
    got <- case text (at "op" op) of
      "submit" ->
        try (submit gw (at "request" op)) >>= \case
          Right r -> pure (Object [("result", String (dumpsText (toolResultToData r)))])
          Left e -> pure (Object [("error", refusal e)])
      "grant" -> do
        let spec' =
              (grantSpec (map method (items (at "capabilities" op))) (double (at "deadline" op)) (int (at "max_calls" op)))
                { specWritablePaths = texts (at "writable_paths" op)
                , specWritableRoots = texts (at "writable_roots" op)
                , specDeniedWritableRoots = texts (at "denied_writable_roots" op)
                , specAllowedArgv = map texts (items (at "allowed_argv" op))
                }
        tryOpenGrant ledger spec' >>= \case
          Right g -> pure (Object [("grant_epoch", Int g.grantEpoch)])
          Left e -> pure (Object [("error", refusal e)])
      "fence" -> do
        writeIORef fence (callFence (bool (at "open" op)) (bool (at "aborted" op)) (double (at "deadline" op)))
        pure Null
      "clock" -> writeIORef now (double (at "value" op)) >> pure Null
      "target" -> writeIORef current (bool (at "current" op)) >> pure Null
      "close" -> closeGrant ledger >> pure Null
      "cleanup" -> (\k -> Object [("removed", Int (fromIntegral k))]) <$> cleanupStages gw
      other -> error ("unknown op " <> show other)
    pure (mismatch here expected got)
  c <- counters gw
  ev <- evidence gw
  pure $
    catMaybes stepMismatches
      <> catMaybes
        [ mismatch (label <> " counters") (at "counters" session) (countersData c)
        , mismatch (label <> " evidence") (at "evidence" session) (evidenceData ev)
        ]

spec :: Spec
spec = describe "hands differential corpus (differential/hands_corpus.py)" $ do
  corpus <- runIO (loadJson corpusFile)

  it "parse_tool_request: normalized requests, rejections and salvaged identities" $ do
    let cases = items (at "requests" corpus)
    length cases `shouldSatisfy` (> 500)
    expectNone $
      catMaybes
        [ mismatch (T.unpack (text (at "label" c))) (Object [("outcome", at "outcome" c), ("salvage", at "salvage" c)]) got
        | c <- cases
        , let input = at "input" c
              (call, episode) = salvagedIdentity input
              got = Object [("outcome", requestOutcome input), ("salvage", Array [String call, String episode])]
        ]

  it "ToolResult/ToolError: to_data and to_model_data bytes, or the refusal" $ do
    let cases = items (at "results" corpus)
    length cases `shouldSatisfy` (> 100)
    expectNone $
      catMaybes [mismatch (show (at "input" c)) (at "outcome" c) (resultOutcome (at "input" c)) | c <- cases]

  it "CapabilityGrant: permits and permits_write_path decisions, or the refusal" $ do
    let grants = at "grants" corpus
        probes = texts (at "write_probes" grants)
        cases = items (at "cases" grants)
    length cases `shouldSatisfy` (> 100)
    expectNone $
      catMaybes [mismatch (show (at "input" c)) (at "outcome" c) (grantOutcome probes (at "input" c)) | c <- cases]

  it "HandsGateway: scripted sessions step by step, final counters and evidence" $ do
    let sessions = items (at "sessions" corpus)
    length sessions `shouldSatisfy` (>= 40)
    concat <$> mapM replaySession sessions >>= expectNone
